{"content": "import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { cache } from 'react'
import type { JsonPlaceholderComment, JsonPlaceholderPost } from '../../../lib/types'
import BackButton from './back-button'

async function getPost(id: string): Promise<JsonPlaceholderPost | null> {
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    })
    if (!res.ok) return null
    return res.json()
  } catch {
    return null
  }
}

async function getComments(id: string): Promise<JsonPlaceholderComment[]> {
  try {
    const res = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
      { next: { revalidate: 300 } }
    )
    return res.json()
  } catch {
    return []
  }
}

// Memoize per-request so generateMetadata and the page share one fetch.
const getCachedPost = cache(getPost)

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: JsonPlaceholderPost[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>
}): Promise<Metadata> {
  const { id } = await params
  const post = await getCachedPost(id)

  if (!post) {
    return { title: 'Not Found' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getCachedPost(id),
    getComments(id),
  ])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
", "path": "app/blog/[id]/page.tsx"}

